entries[5721] = { ["name"] = "Zauberfoliant der Zauberstein-Herstellung", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 34\nBenutzen: Lehrt 'Zauberstein herstellen'.\nZauberstein\nHerbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig\nIn Schildhand geführt\nBenötigt Stufe 31\nBenutzen: Entfernt alle magischen Effekte vom Zaubernden und absorbiert 1 Min. lang 400 Magieschaden.\nAnlegen: Erhöht Eure Chance, einen kritischen Treffer durch Zauber zu erzielen, um 1%.\nBenötigt Seelensplitter" }
